        to = e.get("to", DEFAULT_TO)
        edges.append((a, b, frm, to))
    for e in merges:
        a = tuple(e["a"])
        b = tuple(e["b"])
        frm = e.get("from", 0)
        to = e.get("to", DEFAULT_TO)
        edges.append((a, b, frm, to))

    # Distinct times in first-appearance order.
    times = []
