        t = r["time"]
        if t not in seen_times:
            seen_times.add(t)
            times.append(t)

    # For each time, compute connected components of active edges.
    # Cache canonical subject per (time, subject) to reuse across records.
    time_canonical = {}

    def canonical_at(t):
